 Mappings	verUS,							// inherited regionCode - regionCode to try as a backup to this one. kAllRegions if none.	{		'****',						// resourceID - the type of resource, may be '****' for wildcard		kverRussiaOffset			// IDOffset - the offset to add to ID for resources that support this locale	},		// Direct Mappings - None	{ }};//--------------------------------------------------------------------------------------------------// Other resources//--------------------------------------------------------------------------------------------------resource 'CMNU' (mApple + kverRussiaOffset,#if qNames"mApple",#endifpurgeable) {	mApple,	textMenuProc,	0x7FFFFFFD,	enabled,	apple,	{	"О ^0…", noIcon, noKey, noMark, plain, cAboutApp;		// The ^0 will be dynamically replaced with CurApName	"-",		 noIcon, noKey, noMark, plain, nocommand	}};resource 'CMNU' (mFile + kverRussiaOffset,#if qNames"mFile",#endifpurgeable) {	mFile,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Файл",	{	"Новая",					noIcon, "N",	noMark, plain, cNew;	"Открыть",					noIcon, "O",	noMark, plain, cOpen;	"-",						noIcon, noKey,	noMark, plain, nocommand;	"Закрыть",					noIcon, "W",	noMark, plain, cClose;	"Save",						noIcon, "S",	noMark, plain, cSave;	"Save As…",					noIcon, noKey,	noMark, plain, cSaveAs;	"(R) Revert",					noIcon, noKey,	noMark, plain, cRevert; // missing translation	"-",						noIcon, noKey,	noMark, plain, nocommand;	"Page Setup…",				noIcon, noKey,	noMark, plain, cPageSetup;	"Print",					noIcon, "P",	noMark, plain, cPrint;	"Print One",				noIcon, noKey,	noMark, plain, cPrintOne;	"-",						noIcon, noKey,	noMark, plain, nocommand;	"Завершить",				noIcon, "Q",	noMark, plain, cQuit	}};resource 'CMNU' (mEdit + kverRussiaOffset,#if qNames"mEdit",#endifpurgeable) {	mEdit,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Редактор",	{	"Отменить",					noIcon, "Z",	noMark, plain, cUndo;	"Повторить",				noIcon, "R",	noMark, plain, cRedo; // missing translation	"-",						noIcon, noKey,	noMark, plain, nocommand;	"Вырезать",					noIcon, "X",	noMark, plain, cCut;	"Скопировать",				noIcon, "C",	noMark, plain, cCopy;	"Вставить",					noIcon, "V",	noMark, plain, cPaste;	"Стереть",					noIcon, noKey,	noMark, plain, cClear;	"Выделить все",				noIcon, "A",	noMark, plain, cSelectAll;	"-",						noIcon, noKey,	noMark, plain, nocommand;	"Открыть Конверт",			noIcon, noKey,	noMark, plain, cShowClipboard;	}};